/**
 * Map of Armeniaca's data for the admin hub: where each file lives, what
 * it holds, who updates it, and whether to edit it by hand.
 * Human-readable copy: docs/data-files.md.
 *
 * by:
 *   'tangan'      written by hand; edit freely (on GitHub or locally)
 *   'bot'         rewritten by a GitHub Actions bot; hand edits get overwritten
 *   'elirecorder' published by EliRecorder on the admin's Mac; edit there
 *   'script'      generated by a script in scripts/; edit the source, then re-run
 */

export const REPO = 'Vinzryyy/VinzryyySaga';
export const BRANCH = 'main';
export const githubEdit = (path) => `https://github.com/${REPO}/edit/${BRANCH}/${path}`;
export const githubView = (path) => `https://github.com/${REPO}/blob/${BRANCH}/${path}`;
export const githubHistory = (path) => `https://github.com/${REPO}/commits/${BRANCH}/${path}`;

export const BY = {
  tangan: { label: 'Ditulis tangan', tone: 'emerald', hint: 'Boleh diedit langsung.' },
  bot: { label: 'Bot otomatis', tone: 'amber', hint: 'Ditimpa bot secara berkala; editan tangan akan hilang.' },
  elirecorder: { label: 'EliRecorder', tone: 'sky', hint: 'Diterbitkan EliRecorder dari Mac; edit di EliRecorder, bukan di GitHub.' },
  script: { label: 'Dibuat script', tone: 'stone', hint: 'Hasil script; ubah sumbernya lalu jalankan ulang script-nya.' },
};

